    consonants = set(chr(i) for i in range(ord('a'), ord('z')+1)) - vowels

    right_consonants = [ch for ch in word[::-1] if ch in consonants]
    if len(right_consonants) < 2:
        return ""

    for ch in word[::-1]:
        if ch in vowels:
            return ch
        if ch in consonants:
            break

    return ""

# Test cases
