def minPath(grid, k):
    N = len(grid)
    visited = set()
    path = []

    def backtrack(curr_i, curr_j, steps):
        if steps == k:
            return True
        visited.add((curr_i, curr_j))
        path.append(grid[curr_i][curr_j])
        for x, y in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            new_i, new_j = curr_i + x, curr_j + y
            if 0 <= new_i < N and 0 <= new_j < N and (new_i, new_j) not in visited:
                if backtrack(new_i, new_j, steps+1):
                    return True
        visited.remove((curr_i, curr_j))
        path.pop()

    for i in range(N):
        for j in range(N):
            if backtrack(i, j, 1):
                return path

