def compare_one(a, b):
    a_type = type(a)
    b_type = type(b)

    if a_type == b_type:
        if a_type == int:
            return a if a > b else (b if a < b else None)
        elif a_type == float:
            return a if a > b else (b if a < b else None)
        elif a_type == str:
            a = a.replace(",", ".")
            b = b.replace(",", ".")
            a = float(a) if "." in a else int(a)
            b = float(b) if "." in b else int(b)
            return a if a > b else (b if a < b else None)
    else:
        return None

# Test cases
